<?php
namespace App\Http\Controllers\Admin;
use App\Enums\AvailabilityStatus;use App\Enums\OverallVerificationStatus;use App\Http\Controllers\Controller;use App\Models\CustomerRequirement;use App\Models\DutyType;use App\Models\Service;use App\Models\Worker;use App\Services\WorkerMatchingService;use Illuminate\Http\Request;use Illuminate\View\View;
class WorkerMatchingController extends Controller { public function index(Request $request,WorkerMatchingService $matching):View{$requirements=CustomerRequirement::with(['customer:id,name','service:id,name'])->whereIn('requirement_status',['open','worker_search','shortlisted'])->latest()->get();$selected=$request->filled('requirement')?CustomerRequirement::findOrFail($request->integer('requirement')):null;$workers=$selected?$matching->candidates($selected,$request->all()):collect();return view('admin.matching.index',['requirements'=>$requirements,'requirement'=>$selected?->load(['customer','service','dutyType','householdDetail','accommodationDetail','workingCondition','workerPreference']),'workers'=>$workers,'services'=>Service::where('is_active',true)->get(),'dutyTypes'=>DutyType::where('is_active',true)->get(),'cities'=>Worker::distinct()->orderBy('city')->pluck('city'),'availabilities'=>AvailabilityStatus::cases(),'verifications'=>OverallVerificationStatus::cases()]);} public function requirement(CustomerRequirement $requirement):mixed{return redirect()->route('admin.worker-matching.index',['requirement'=>$requirement->id]);} }
